const msg = $input.first().json;
const text = (msg.message?.text || '').trim();
const chatId = String(msg.message?.chat?.id || msg.message?.from?.id || '');

if (!text || !chatId) {
  return [{ json: { intent: 'ignore', args: {}, sql: 'SELECT 1 AS placeholder', chatId } }];
}

let intent = 'unknown';
let args = {};
let sql = 'SELECT 1 AS placeholder';

const cleanText = text.replace(/@[A-Za-z_]+bot/i, '').trim();
const parts = cleanText.split(/\s+/);
const cmd = parts[0]?.toLowerCase() || '';
const arg = parts[1] || '';
const lowerText = cleanText.toLowerCase();

// === COMMAND PARSING ===
if (cleanText.startsWith('/')) {
  switch(cmd) {
    case '/start':
    case '/help':
    case '/pagalba':
      intent = 'help';
      break;
    case '/today':
    case '/siandien':
      intent = 'today';
      break;
    case '/tomorrow':
    case '/rytoj':
      intent = 'tomorrow';
      break;
    case '/week':
    case '/savaite':
      intent = 'week';
      break;
    case '/available':
    case '/laisvi':
      intent = 'available';
      break;
    case '/stats':
    case '/statistika':
      intent = 'stats';
      break;
    case '/delivered':
    case '/pristatyta':
      if (!arg || isNaN(parseInt(arg)) || parseInt(arg) <= 0) {
        intent = 'error'; args.msg = '\u26a0\ufe0f Nurodykite u\u017esakymo ID, pvz: /delivered 5'; break;
      }
      intent = 'delivered'; args.id = parseInt(arg);
      break;
    case '/returned':
    case '/grazinta':
      if (!arg || isNaN(parseInt(arg)) || parseInt(arg) <= 0) {
        intent = 'error'; args.msg = '\u26a0\ufe0f Nurodykite u\u017esakymo ID, pvz: /returned 5'; break;
      }
      intent = 'returned'; args.id = parseInt(arg);
      break;
    case '/paid':
    case '/apmoketa':
      if (!arg || isNaN(parseInt(arg)) || parseInt(arg) <= 0) {
        intent = 'error'; args.msg = '\u26a0\ufe0f Nurodykite u\u017esakymo ID, pvz: /paid 5'; break;
      }
      intent = 'paid'; args.id = parseInt(arg);
      break;
    case '/deposit':
    case '/avansas':
      if (!arg || isNaN(parseInt(arg)) || parseInt(arg) <= 0) {
        intent = 'error'; args.msg = '\u26a0\ufe0f Nurodykite u\u017esakymo ID, pvz: /deposit 5'; break;
      }
      intent = 'deposit'; args.id = parseInt(arg);
      break;
    case '/cancel':
    case '/atsaukti':
      if (!arg || isNaN(parseInt(arg)) || parseInt(arg) <= 0) {
        intent = 'error'; args.msg = '\u26a0\ufe0f Nurodykite u\u017esakymo ID, pvz: /cancel 5'; break;
      }
      intent = 'cancel'; args.id = parseInt(arg);
      break;
    case '/clean':
    case '/valyti':
      if (!arg || isNaN(parseInt(arg)) || parseInt(arg) <= 0) {
        intent = 'error'; args.msg = '\u26a0\ufe0f Nurodykite \u012frangos ID, pvz: /clean 3'; break;
      }
      intent = 'clean'; args.id = parseInt(arg);
      break;
    default:
      intent = 'unknown';
  }
} else {
  // === NATURAL LANGUAGE (Lithuanian) ===
  if (/\b(siandien|\u0161iandien|\u0161iandie|kas siandien|kas \u0161iandien)\b/i.test(lowerText)) {
    intent = 'today';
  } else if (/\b(rytoj|ryt\b)/i.test(lowerText)) {
    intent = 'tomorrow';
  } else if (/(savait|savaite|savait\u0117|\u0161i\u0105 savait\u0119|sia savaite)/i.test(lowerText)) {
    intent = 'week';
  } else if (/(laisv|turimos|kiek laisv)/i.test(lowerText)) {
    intent = 'available';
  } else if (/(statistik|apzvalga|ap\u017evalga)/i.test(lowerText)) {
    intent = 'stats';
  } else if (/(pagalb|komand)/i.test(lowerText)) {
    intent = 'help';
  }
}

// === BUILD SQL ===
const BOOKING_FIELDS = `b.id, b.event_date, b.event_time, b.pickup_time,
  b.delivery_address, b.city, b.status, b.price,
  b.deposit_amount, b.deposit_paid, b.payment_status,
  c.name AS customer_name, c.phone AS customer_phone,
  COALESCE((SELECT json_agg(json_build_object('name', e.name, 'icon', e.icon))
    FROM batutynas.booking_equipment be
    JOIN batutynas.equipment e ON e.id = be.equipment_id
    WHERE be.booking_id = b.id), '[]'::json) AS equipment`;

const BOOKING_JOIN = `FROM batutynas.bookings b
  JOIN batutynas.contacts c ON c.id = b.contact_id`;

switch(intent) {
  case 'today':
    sql = `SELECT COALESCE(json_agg(row_to_json(bk.*) ORDER BY bk.event_time), '[]'::json) AS result
      FROM (SELECT ${BOOKING_FIELDS} ${BOOKING_JOIN}
        WHERE b.event_date = CURRENT_DATE AND b.status NOT IN ('Cancelled')) bk`;
    break;

  case 'tomorrow':
    sql = `SELECT COALESCE(json_agg(row_to_json(bk.*) ORDER BY bk.event_time), '[]'::json) AS result
      FROM (SELECT ${BOOKING_FIELDS} ${BOOKING_JOIN}
        WHERE b.event_date = CURRENT_DATE + INTERVAL '1 day' AND b.status NOT IN ('Cancelled')) bk`;
    break;

  case 'week':
    sql = `SELECT COALESCE(json_agg(row_to_json(bk.*) ORDER BY bk.event_date, bk.event_time), '[]'::json) AS result
      FROM (SELECT ${BOOKING_FIELDS} ${BOOKING_JOIN}
        WHERE b.event_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '6 days'
          AND b.status NOT IN ('Cancelled')) bk`;
    break;

  case 'available':
    sql = `SELECT json_build_object(
      'available', COALESCE((
        SELECT json_agg(json_build_object('id', e.id, 'name', e.name, 'icon', e.icon, 'category', e.category) ORDER BY e.category, e.name)
        FROM batutynas.equipment e
        WHERE e.id NOT IN (
          SELECT be.equipment_id FROM batutynas.booking_equipment be
          JOIN batutynas.bookings b ON b.id = be.booking_id
          WHERE b.event_date = CURRENT_DATE AND b.status IN ('Confirmed', 'Delivered')
        )
      ), '[]'::json),
      'booked_today', COALESCE((
        SELECT json_agg(json_build_object('id', e.id, 'name', e.name, 'icon', e.icon))
        FROM batutynas.equipment e
        WHERE e.id IN (
          SELECT be.equipment_id FROM batutynas.booking_equipment be
          JOIN batutynas.bookings b ON b.id = be.booking_id
          WHERE b.event_date = CURRENT_DATE AND b.status IN ('Confirmed', 'Delivered')
        )
      ), '[]'::json)
    ) AS result`;
    break;

  case 'stats':
    sql = `SELECT json_build_object(
      'today_bookings', (SELECT COUNT(*) FROM batutynas.bookings WHERE event_date = CURRENT_DATE AND status NOT IN ('Cancelled')),
      'week_bookings', (SELECT COUNT(*) FROM batutynas.bookings WHERE event_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '6 days' AND status NOT IN ('Cancelled')),
      'month_revenue', (SELECT COALESCE(SUM(price), 0) FROM batutynas.bookings WHERE event_date >= date_trunc('month', CURRENT_DATE) AND status IN ('Completed', 'Delivered', 'Confirmed')),
      'unpaid_deposits', (SELECT COUNT(*) FROM batutynas.bookings WHERE event_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '7 days' AND deposit_paid = FALSE AND status = 'Confirmed'),
      'total_equipment', (SELECT COUNT(*) FROM batutynas.equipment),
      'available_equipment', (SELECT COUNT(*) FROM batutynas.equipment WHERE status = 'Available'),
      'needs_cleaning', (SELECT COUNT(*) FROM batutynas.equipment WHERE status = 'Needs Cleaning')
    ) AS result`;
    break;

  case 'delivered':
    sql = `WITH updated AS (
      UPDATE batutynas.bookings SET status = 'Delivered', updated_at = NOW()
      WHERE id = ${args.id} AND status = 'Confirmed'
      RETURNING id, status, event_date, delivery_address, city
    )
    SELECT COALESCE(
      (SELECT json_build_object('id', id, 'status', status, 'event_date', event_date::text, 'delivery_address', delivery_address, 'city', city) FROM updated),
      NULL
    ) AS result`;
    break;

  case 'returned':
    sql = `WITH updated AS (
      UPDATE batutynas.bookings SET status = 'Completed', updated_at = NOW()
      WHERE id = ${args.id} AND status = 'Delivered'
      RETURNING id, status, event_date, delivery_address, city
    )
    SELECT COALESCE(
      (SELECT json_build_object('id', id, 'status', status, 'event_date', event_date::text, 'delivery_address', delivery_address, 'city', city) FROM updated),
      NULL
    ) AS result`;
    break;

  case 'paid':
    sql = `WITH updated AS (
      UPDATE batutynas.bookings SET payment_status = 'Paid', updated_at = NOW()
      WHERE id = ${args.id}
      RETURNING id, status, payment_status, price
    )
    SELECT COALESCE(
      (SELECT json_build_object('id', id, 'status', status, 'payment_status', payment_status, 'price', price) FROM updated),
      NULL
    ) AS result`;
    break;

  case 'deposit':
    sql = `WITH updated AS (
      UPDATE batutynas.bookings SET deposit_paid = TRUE, updated_at = NOW()
      WHERE id = ${args.id}
      RETURNING id, status, deposit_paid, deposit_amount
    )
    SELECT COALESCE(
      (SELECT json_build_object('id', id, 'status', status, 'deposit_paid', deposit_paid, 'deposit_amount', deposit_amount) FROM updated),
      NULL
    ) AS result`;
    break;

  case 'cancel':
    sql = `WITH updated AS (
      UPDATE batutynas.bookings SET status = 'Cancelled', updated_at = NOW()
      WHERE id = ${args.id} AND status NOT IN ('Cancelled', 'Completed')
      RETURNING id, status, event_date
    )
    SELECT COALESCE(
      (SELECT json_build_object('id', id, 'status', status, 'event_date', event_date::text) FROM updated),
      NULL
    ) AS result`;
    break;

  case 'clean':
    sql = `WITH updated AS (
      UPDATE batutynas.equipment SET status = 'Available', last_cleaned = NOW(), updated_at = NOW()
      WHERE id = ${args.id}
      RETURNING id, name, icon, status
    )
    SELECT COALESCE(
      (SELECT json_build_object('id', id, 'name', name, 'icon', icon, 'status', status) FROM updated),
      NULL
    ) AS result`;
    break;

  case 'help':
  case 'error':
  case 'unknown':
  case 'ignore':
  default:
    sql = 'SELECT 1 AS placeholder';
    break;
}

return [{ json: { intent, args, sql, chatId } }];

const { intent, args } = $('Parse Intent').first().json;
const row = $input.first().json;
let result;

if (['help', 'error', 'unknown', 'ignore'].includes(intent)) {
  result = null;
} else {
  result = typeof row.result === 'string' ? JSON.parse(row.result) : row.result;
}

let reply = '';

// Lithuanian day names
const dayNames = ['Sekmadienis', 'Pirmadienis', 'Antradienis', 'Tre\u010diadienis', 'Ketvirtadienis', 'Penktadienis', '\u0160e\u0161tadienis'];

function formatDate(dateStr) {
  const d = new Date(dateStr + 'T00:00:00');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${month}-${day} (${dayNames[d.getDay()]})`;
}

function formatBooking(b) {
  const statusIcons = { 'Confirmed': '\ud83d\udfe1', 'Delivered': '\ud83d\ude9b', 'Completed': '\u2705', 'Cancelled': '\u274c' };
  const payIcon = b.payment_status === 'Paid' ? '\ud83d\udcb0' : (b.deposit_paid ? '\ud83d\udd35' : '\ud83d\udd34');
  const icon = statusIcons[b.status] || '\u2b1c';
  const equip = Array.isArray(b.equipment) ? b.equipment.map(e => e.icon || '\ud83c\udfaa').join('') : '';

  let line = `${icon} <b>#${b.id}</b> ${(b.event_time || '?').substring(0,5)} \u2192 ${(b.pickup_time || '?').substring(0,5)}`;
  line += `\n   \ud83d\udccd ${b.delivery_address}, ${b.city}`;
  line += `\n   \ud83d\udc64 ${b.customer_name} | \ud83d\udcde ${b.customer_phone}`;
  line += `\n   ${equip} | ${payIcon} \u20ac${b.price || 0}`;
  if (!b.deposit_paid && b.status === 'Confirmed') {
    line += ` \u26a0\ufe0f Avansas nemok\u0117tas!`;
  }
  return line;
}

switch(intent) {
  case 'help':
    reply = `\ud83e\udd16 <b>Batutynas Bot</b>\n\n` +
      `\ud83d\udccb <b>Per\u017ei\u016bra:</b>\n` +
      `/today - \u0160iandienos u\u017esakymai\n` +
      `/tomorrow - Rytojaus u\u017esakymai\n` +
      `/week - Savait\u0117s u\u017esakymai\n` +
      `/available - Laisva \u012franga\n` +
      `/stats - Statistika\n\n` +
      `\u270f\ufe0f <b>Veiksmai:</b>\n` +
      `/delivered <i>ID</i> - Pristatyta\n` +
      `/returned <i>ID</i> - Gr\u0105\u017einta\n` +
      `/paid <i>ID</i> - Apmok\u0117ta\n` +
      `/deposit <i>ID</i> - Avansas sumok\u0117tas\n` +
      `/cancel <i>ID</i> - At\u0161aukti\n` +
      `/clean <i>ID</i> - \u012eranga i\u0161valyta\n\n` +
      `\ud83d\udcac <b>Arba ra\u0161ykite lietuvi\u0161kai:</b>\n` +
      `"\u0161iandien", "rytoj", "savait\u0117", "laisvi", "statistika"`;
    break;

  case 'today':
  case 'tomorrow':
  case 'week': {
    const bookings = Array.isArray(result) ? result : [];
    const label = intent === 'today' ? '\ud83d\udcc5 \u0160iandien' : intent === 'tomorrow' ? '\ud83d\udcc5 Rytoj' : '\ud83d\udcc5 \u0160i savait\u0117';

    if (bookings.length === 0) {
      reply = `${label}: U\u017esakym\u0173 n\u0117ra \ud83c\udf89`;
    } else {
      reply = `${label} (${bookings.length} u\u017es.):\n`;

      if (intent === 'week') {
        const byDate = {};
        bookings.forEach(b => {
          const d = (b.event_date || '').substring(0, 10);
          if (!byDate[d]) byDate[d] = [];
          byDate[d].push(b);
        });
        for (const [date, bks] of Object.entries(byDate)) {
          reply += `\n\ud83d\udcc6 <b>${formatDate(date)}</b>\n`;
          bks.forEach(b => { reply += formatBooking(b) + '\n'; });
        }
      } else {
        bookings.forEach(b => { reply += '\n' + formatBooking(b) + '\n'; });
      }
    }
    break;
  }

  case 'available': {
    const avail = result?.available || [];
    const booked = result?.booked_today || [];
    reply = `\ud83c\udfaa <b>\u012erangos statusas</b>\n\n`;
    reply += `\u2705 <b>Laisva (${avail.length}):</b>\n`;
    if (avail.length === 0) {
      reply += `  Visi u\u017eimti!\n`;
    } else {
      avail.forEach(e => { reply += `  ${e.icon || '\ud83c\udfaa'} #${e.id} ${e.name}\n`; });
    }
    if (booked.length > 0) {
      reply += `\n\ud83d\udd12 <b>U\u017eimta \u0161iandien (${booked.length}):</b>\n`;
      booked.forEach(e => { reply += `  ${e.icon || '\ud83c\udfaa'} ${e.name}\n`; });
    }
    break;
  }

  case 'stats': {
    reply = `\ud83d\udcca <b>Statistika</b>\n\n`;
    reply += `\ud83d\udcc5 \u0160iandien: ${result.today_bookings} u\u017es.\n`;
    reply += `\ud83d\udcc5 \u0160i savait\u0117: ${result.week_bookings} u\u017es.\n`;
    reply += `\ud83d\udcb0 M\u0117nesio pajamos: \u20ac${result.month_revenue}\n`;
    reply += `\u26a0\ufe0f Nemok\u0117ti avansai: ${result.unpaid_deposits}\n`;
    reply += `\ud83c\udfaa \u012eranga: ${result.available_equipment}/${result.total_equipment} laisva\n`;
    if (Number(result.needs_cleaning) > 0) {
      reply += `\ud83e\uddf9 Reikia valyti: ${result.needs_cleaning}\n`;
    }
    break;
  }

  case 'delivered': {
    if (!result) {
      reply = `\u26a0\ufe0f U\u017esakymas #${args.id} nerastas arba statusas netinkamas (turi b\u016bti \"Confirmed\")`;
    } else {
      reply = `\ud83d\ude9b U\u017esakymas <b>#${result.id}</b> pa\u017eym\u0117tas kaip <b>Pristatyta</b>\n\ud83d\udccd ${result.delivery_address}, ${result.city}`;
    }
    break;
  }

  case 'returned': {
    if (!result) {
      reply = `\u26a0\ufe0f U\u017esakymas #${args.id} nerastas arba statusas netinkamas (turi b\u016bti \"Delivered\")`;
    } else {
      reply = `\u2705 U\u017esakymas <b>#${result.id}</b> pa\u017eym\u0117tas kaip <b>Gr\u0105\u017einta/Atlikta</b>\n\ud83d\udccd ${result.delivery_address}, ${result.city}`;
    }
    break;
  }

  case 'paid': {
    if (!result) {
      reply = `\u26a0\ufe0f U\u017esakymas #${args.id} nerastas`;
    } else {
      reply = `\ud83d\udcb0 U\u017esakymas <b>#${result.id}</b> \u2014 mok\u0117jimas pa\u017eym\u0117tas kaip <b>Apmok\u0117ta</b> (\u20ac${result.price})`;
    }
    break;
  }

  case 'deposit': {
    if (!result) {
      reply = `\u26a0\ufe0f U\u017esakymas #${args.id} nerastas`;
    } else {
      reply = `\ud83d\udd35 U\u017esakymas <b>#${result.id}</b> \u2014 avansas <b>sumok\u0117tas</b> (\u20ac${result.deposit_amount})`;
    }
    break;
  }

  case 'cancel': {
    if (!result) {
      reply = `\u26a0\ufe0f U\u017esakymas #${args.id} nerastas arba jau at\u0161auktas/atliktas`;
    } else {
      reply = `\u274c U\u017esakymas <b>#${result.id}</b> <b>at\u0161auktas</b>`;
    }
    break;
  }

  case 'clean': {
    if (!result) {
      reply = `\u26a0\ufe0f \u012eranga #${args.id} nerasta`;
    } else {
      reply = `\ud83e\uddf9 ${result.icon || '\ud83c\udfaa'} <b>${result.name}</b> pa\u017eym\u0117ta kaip <b>I\u0161valyta</b> \u2705`;
    }
    break;
  }

  case 'error':
    reply = args.msg || '\u26a0\ufe0f Klaida. Naudokite /help';
    break;

  case 'ignore':
    reply = '';
    break;

  case 'unknown':
  default:
    reply = `\ud83e\udd14 Nesupratau. Naudokite /help arba ra\u0161ykite lietuvi\u0161kai (pvz. \"\u0161iandien\", \"rytoj\")`;
    break;
}

return [{ json: { reply } }];
